import * as T from './vendor/three.module.js';
export function installEldergrove({scene,camera,colliders,pause,rewards,getCurrentSeat=()=>null}){
 const root=new T.Group();root.name='Eldergrove · Great Elder Tree clearing';scene.add(root);
 const mat=color=>new T.MeshStandardMaterial({color,roughness:.85}),wood=mat('#755039'),bark=mat('#514332'),leaf=mat('#426a42'),leafLight=mat('#658c4c'),gold=mat('#d7b260'),path=mat('#b9ad89'),moss=mat('#517b48');
 const add=(g,m,x,y,z)=>{const o=new T.Mesh(g,m);o.position.set(x,y,z);o.castShadow=o.receiveShadow=true;root.add(o);return o;};
 const box=(x,y,z,w,h,d,m,solid=false)=>{const o=add(new T.BoxGeometry(w,h,d),m,x,y,z);if(solid)colliders.push({x,z,w:w/2+.3,d:d/2+.3});return o;};
 box(34,.03,119,27,.1,24,moss);box(26,.09,116,22,.13,3.2,path);box(35,.1,122,23,.12,3.2,path);box(25,.08,122,3.2,.1,12,path);box(44,.09,119,3.2,.12,14,path);
 add(new T.CylinderGeometry(9,9,.12,48),path,35,.12,116);add(new T.CylinderGeometry(6,6,.14,40),moss,35,.2,116);
 // A broad ancient tree, with raised roots and high branches around an open walking ring.
 add(new T.CylinderGeometry(1.05,1.8,10,16),bark,35,5,116);colliders.push({x:35,z:116,r:2.5});
 for(let i=0;i<7;i++){const a=i*Math.PI*2/7;const pts=[[35+Math.sin(a)*2,.3,116+Math.cos(a)*2],[35+Math.sin(a)*1.1,4,116+Math.cos(a)*1.1],[35+Math.sin(a)*3,8,116+Math.cos(a)*3],[35+Math.sin(a)*5.5,10,116+Math.cos(a)*5.5]].map(p=>new T.Vector3(...p));add(new T.TubeGeometry(new T.CatmullRomCurve3(pts),12,.28,7,false),bark,0,0,0);const canopy=add(new T.SphereGeometry(3.7,12,9),i%2?leaf:leafLight,35+Math.sin(a)*4,11.5,116+Math.cos(a)*4);canopy.scale.y=.75;}
 for(const [x,z] of [[23,129],[31,130],[43,130],[49,126],[49,112],[45,105],[28,106]]){add(new T.CylinderGeometry(.2,.4,6,9),bark,x,3,z);add(new T.SphereGeometry(2.3,10,8),leaf,x,7,z);colliders.push({x,z,r:.45});}
 const glow=new T.MeshStandardMaterial({color:'#ffe3a1',emissive:'#ffd070',emissiveIntensity:.6});for(const [x,z] of [[26,118],[42,121],[33,123]]){box(x,1.1,z,.09,2.2,.09,wood,true);add(new T.SphereGeometry(.15,9,6),glow,x,2.3,z);}
 function sign(text,x,y,z,w){const c=document.createElement('canvas');c.width=1024;c.height=160;const ctx=c.getContext('2d');ctx.fillStyle='#203d31';ctx.fillRect(0,0,1024,160);ctx.fillStyle='#ffedbc';ctx.textAlign='center';ctx.font='42px Georgia';ctx.fillText(text,512,98);const texture=new T.CanvasTexture(c);texture.colorSpace=T.SRGBColorSpace;add(new T.PlaneGeometry(w,.8),new T.MeshStandardMaterial({map:texture,side:T.DoubleSide}),x,y,z);}
 sign('ELDERGROVE · GREAT ELDER TREE',35,2.7,125,9);for(const x of [31,39])box(x,1.3,125,.12,2.6,.12,wood,true);
 // Open craft shelter and a small interpretation garden.
 box(46,.15,118,4,.2,5,wood);box(46,3.4,118,4.8,.22,5.8,leaf);for(const x of [44,48])for(const z of [115.5,120.5])box(x,1.7,z,.14,3.4,.14,wood,true);
 box(46,.9,117,2.5,.18,1.1,wood,true);for(const x of [45,47])box(x,.4,117,.12,.8,.7,wood);add(new T.CylinderGeometry(.35,.3,.22,12),gold,46,1.1,117);box(45.4,1.1,117,.5,.25,.3,wood);sign('WOODCRAFT',46,2.45,117,3.6);
 for(const x of [25,28]){box(x,.45,125,2,.7,1.6,wood,true);for(let i=0;i<6;i++){const px=x-.6+(i%3)*.6,pz=124.7+Math.floor(i/3)*.6;box(px,.95,pz,.035,.5,.035,leaf);add(new T.SphereGeometry(.22,7,5),i%2?leaf:leafLight,px,1.2,pz);}}
 sign('FOREST HERB GARDEN',26.5,2.4,126,5);
 const seats=[];for(const [x,z,name] of [[30,111,'Great Elder Tree storytelling bench'],[40,111,'Great Elder Tree storytelling bench'],[46,123,'Eldergrove craft lounge bench']]){box(x,.6,z,3,.2,.85,wood,true);box(x,1.05,z+.4,3,.85,.13,wood);seats.push({name,x,z,y:1.45,yaw:x===46?0:Math.PI,approach:{x,z:z-1.3},kind:'eldergrove'});}
 const points=[{id:'tree',x:35,z:121,name:'Great Elder Tree',title:'Gather beneath the Great Elder Tree',text:'Eldergrove’s village description places the Great Elder Tree at its heart. The community gathers around it for seasonal festivals. This clearing begins a new 3D interpretation of that shared gathering place.'},{id:'craft',x:46,z:119,name:'Eldergrove woodcraft shelter',title:'A tradition of woodcraft',text:'Eldergrove’s artisans are known for wooden furniture and decorative objects. Imagine a useful object you could make for a neighbor. The little carving here celebrates that tradition.'},{id:'herbs',x:26.5,z:122.8,name:'Eldergrove herb garden',title:'Learn from the forest',text:'The original village description includes herbal knowledge and remedies made from forest plants. This small display celebrates that community tradition. It is a fictional exhibit, with no plant identification or treatment advice.'}];
 let active=0;const seen=()=>new Set(points.flatMap((p,i)=>rewards.state().done.includes('eldergrove-stop-'+p.id)?[i]:[])),owned=()=>rewards.state().done.includes('eldergrove-trail');const nearest=()=>points.findIndex(p=>Math.hypot(camera.position.x-p.x,camera.position.z-p.z)<1.65);
 const dialog=document.createElement('dialog');dialog.id='eldergroveMenu';dialog.setAttribute('aria-labelledby','eldergroveTitle');const title=document.createElement('h2');title.id='eldergroveTitle';const body=document.createElement('p');const credit=document.createElement('p');credit.textContent='Inspired by Eldergrove’s description on krownlandia.com. This clearing is the first visitable area of the village.';const status=document.createElement('p');status.id='eldergroveStatus';status.setAttribute('role','status');const discover=document.createElement('button');discover.id='eldergroveDiscover';const next=document.createElement('button');next.id='eldergroveNext';const reward=document.createElement('button');reward.id='eldergroveRewards';reward.textContent='Find Eldergrove rewards';reward.onclick=()=>{if(!canAct())return;pause();rewards.guideTo('eldergrove');dialog.close();};const close=document.createElement('button');close.id='eldergroveClose';close.textContent='Return to the clearing';close.onclick=()=>{pause();dialog.close();};dialog.append(title,body,credit,status,discover,next,reward,close);document.body.append(dialog);
 const tramGuide=document.createElement('button');tramGuide.id='eldergroveTram';tramGuide.textContent='Walk to Eldergrove homes tram stop';tramGuide.onclick=()=>{if(!canAct())return;pause();rewards.guideToPoint({x:2.2,z:161,name:'Eldergrove homes tram stop'});dialog.close();};dialog.append(tramGuide);
 const checklist=document.createElement('p');checklist.id='eldergroveChecklist';dialog.append(checklist);
 const css=document.createElement('link');css.rel='stylesheet';css.href='eldergrove.css';document.head.append(css);
 const seatTopic=()=>{const i=seats.indexOf(getCurrentSeat());return i<0?-1:i===2?1:0;};
 const canAct=()=>dialog.open&&(nearest()===active||seatTopic()===active);
 function render(){checklist.textContent=points.map((p,i)=>(owned()||seen().has(i)?'✓ ':'○ ')+p.name).join(' · ');title.textContent=points[active].title;body.textContent=points[active].text;discover.textContent=seen().has(active)||owned()?'Discovery recorded':'Record this discovery';discover.disabled=seen().has(active)||owned()||seatTopic()>=0;if(seatTopic()>=0&&!seen().has(active)&&!owned())discover.textContent='Visit the discovery stop to record';const todo=points.findIndex((p,i)=>!seen().has(i));next.hidden=owned()||todo===-1;next.textContent=todo<0?'Trail complete':'Walk to '+points[todo].name;next.onclick=()=>{if(canAct()&&todo>=0){pause();rewards.guideToPoint(points[todo]);dialog.close();}};const collected=rewards.state().claims.includes('eldergrove:task');reward.textContent=owned()&&!collected?'Find my 20-point forest reward':'Find Eldergrove rewards';status.textContent=owned()?(collected?'Your Woodcarved Leaf and 20-point task reward are collected. You can display the leaf at home.':'Forest discoveries complete. Your Woodcarved Leaf is collected and your 20-point task reward is ready at the Eldergrove rewards station.'):seen().size+' / 3 places discovered · Explore all three to earn a Woodcarved Leaf and unlock 20 task points.';if(!rewards.state().saved)status.textContent+=' Progress lasts for this visit; browser storage is unavailable.';}
 discover.onclick=()=>{if(!canAct()||seatTopic()>=0||nearest()!==active||owned()||seen().has(active))return;rewards.recordEldergrove(points[active].id);render();};
 return {points,seats,progress:()=>({count:owned()?3:seen().size,next:owned()?null:points.find((p,i)=>!seen().has(i))}),collection:()=>owned()?[{id:'eldergrove-leaf',name:'Eldergrove Woodcarved Leaf',color:'#bb9159'}]:[],open(){const i=seatTopic()>=0?seatTopic():nearest();if(i<0||dialog.open)return false;active=i;pause();render();dialog.showModal();return true;},get near(){return nearest()>=0},get isOpen(){return dialog.open}};
}
